func init() {
	for path, metadata := range collaborationOptionsResponses {
		workItemOptionsResponses[path] = metadata
	}
}

type collaborationProtocolAuthorizer struct {
	core, collaboration systemapi.WorkItemProtocolAuthorizer
}

func (a collaborationProtocolAuthorizer) AuthorizeWorkItemProtocol(ctx context.Context, q systemapi.WorkItemProtocolResource) (systemapi.WorkItemProtocolMetadata, error) {
	for _, p := range collaborationProtocols {
		if p.pattern == q.Pattern {
			return a.collaboration.AuthorizeWorkItemProtocol(ctx, q)
		}
	}
	return a.core.AuthorizeWorkItemProtocol(ctx, q)
}
func mountCollaborationHeads(mux loomhttp.Muxer, s *server.Server, policy loomhttp.RuntimeCORSPolicy) {
	for _, mount := range s.Mounts {
		if mount.Verb != http.MethodGet {
			continue
		}
		p := workItemProtocolForPattern(mount.Pattern)
		if !p.derivedHead {
			continue
		}
		handler, ok := reflect.ValueOf(s).Elem().FieldByName(mount.Method).Interface().(http.Handler)
		if !ok || handler == nil {
			panic("missing native collaboration handler " + mount.Method)
		}
		loomhttp.MountDerivedHead(mux, p.pattern, policy.Handler(loomhttp.AsHandlerFunc(handler)))
	}
}
